CREATE TABLE profiles (id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,name VARCHAR(80) NOT NULL,avatar_id VARCHAR(255) NOT NULL DEFAULT 'default.png',is_default BOOLEAN NOT NULL DEFAULT FALSE,is_kids BOOLEAN NOT NULL DEFAULT FALSE,is_active BOOLEAN NOT NULL DEFAULT TRUE,pin_hash VARCHAR(255),max_age_rating INT NOT NULL DEFAULT 18,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,last_used_at VARCHAR(40),INDEX idx_profiles_user(user_id,is_active),CONSTRAINT chk_profile_age CHECK(max_age_rating IN (0,10,12,14,16,18)),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO profiles(id,user_id,name,avatar_id,is_default,is_kids,is_active,max_age_rating,created_at,updated_at) SELECT UUID(),id,display_name,'default.png',TRUE,FALSE,TRUE,18,created_at,updated_at FROM users;
CREATE TABLE profile_library_access (profile_id VARCHAR(36) NOT NULL,library_id VARCHAR(36) NOT NULL,is_allowed BOOLEAN NOT NULL DEFAULT TRUE,created_at VARCHAR(40) NOT NULL,updated_at VARCHAR(40) NOT NULL,PRIMARY KEY(profile_id,library_id),INDEX idx_profile_library_access_library(library_id),FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE,FOREIGN KEY(library_id) REFERENCES libraries(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO profile_library_access(profile_id,library_id,is_allowed,created_at,updated_at) SELECT p.id,l.id,TRUE,p.created_at,p.updated_at FROM profiles p JOIN libraries l ON l.deleted_at IS NULL AND l.is_active=TRUE WHERE p.is_default=TRUE AND (l.privacy='PUBLIC' OR EXISTS(SELECT 1 FROM user_library_access ula WHERE ula.user_id=p.user_id AND ula.library_id=l.id AND ula.can_view=TRUE) OR EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=p.user_id AND r.name='Administrator'));
ALTER TABLE user_favorites ADD COLUMN profile_id VARCHAR(36) NULL AFTER user_id;
UPDATE user_favorites f JOIN profiles p ON p.user_id=f.user_id AND p.is_default=TRUE SET f.profile_id=p.id;
ALTER TABLE user_favorites MODIFY profile_id VARCHAR(36) NOT NULL,DROP INDEX uq_user_favorite,ADD UNIQUE KEY uq_profile_favorite(profile_id,media_item_id),ADD INDEX idx_user_favorites_profile_created(profile_id,created_at),ADD FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE playback_sessions ADD COLUMN profile_id VARCHAR(36) NULL AFTER user_id;
UPDATE playback_sessions s JOIN profiles p ON p.user_id=s.user_id AND p.is_default=TRUE SET s.profile_id=p.id;
ALTER TABLE playback_sessions MODIFY profile_id VARCHAR(36) NOT NULL,ADD INDEX idx_playback_sessions_profile(profile_id,last_activity_at),ADD FOREIGN KEY(profile_id) REFERENCES profiles(id);
ALTER TABLE playback_progress ADD COLUMN profile_id VARCHAR(36) NULL AFTER user_id;
UPDATE playback_progress x JOIN profiles p ON p.user_id=x.user_id AND p.is_default=TRUE SET x.profile_id=p.id;
ALTER TABLE playback_progress MODIFY profile_id VARCHAR(36) NOT NULL,DROP INDEX uq_progress_user_content,ADD UNIQUE KEY uq_progress_profile_content(profile_id,content_key),ADD INDEX idx_playback_progress_profile(profile_id,updated_at),ADD FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE playback_history ADD COLUMN profile_id VARCHAR(36) NULL AFTER user_id;
UPDATE playback_history h JOIN profiles p ON p.user_id=h.user_id AND p.is_default=TRUE SET h.profile_id=p.id;
ALTER TABLE playback_history MODIFY profile_id VARCHAR(36) NOT NULL,DROP INDEX uq_history_user_content,ADD UNIQUE KEY uq_history_profile_content(profile_id,content_key),ADD INDEX idx_playback_history_profile(profile_id,last_watched_at),ADD FOREIGN KEY(profile_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE media_items ADD COLUMN content_age_rating INT NULL,ADD INDEX idx_media_items_age_rating(content_age_rating,library_id);
CREATE TABLE parental_control_settings (id INT PRIMARY KEY,unknown_kids_policy VARCHAR(24) NOT NULL DEFAULT 'BLOCK_FOR_KIDS',updated_at VARCHAR(40) NOT NULL,CONSTRAINT chk_unknown_kids_policy CHECK(unknown_kids_policy IN ('ALLOW','BLOCK_FOR_KIDS'))) ENGINE=InnoDB;
INSERT INTO parental_control_settings(id,unknown_kids_policy,updated_at) VALUES(1,'BLOCK_FOR_KIDS',UTC_TIMESTAMP());
